import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Filler,
} from 'chart.js';
import { useAuth } from '../context/AuthContext';
import { getAchievements, getHistory, getInsights, getWeeklyReport } from '../services/api';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Filler);

const riskBadge = (p) => {
  if (!p) return '—';
  const cls = p.includes('High') ? 'risk-high' : p.includes('Moderate') ? 'risk-moderate' : 'risk-low';
  const icon = p.includes('High') ? 'bi-exclamation-triangle' : p.includes('Moderate') ? 'bi-dash-circle' : 'bi-check-circle';
  return <span className={`risk-badge ${cls}`}><i className={`bi ${icon}`} /> {p}</span>;
};

const QUICK_ACTIONS = [
  { to: '/mood', icon: 'bi-emoji-smile', label: 'Log Mood' },
  { to: '/assessment', icon: 'bi-clipboard2-pulse', label: 'Assessment' },
  { to: '/breathing', icon: 'bi-wind', label: 'Breathe' },
  { to: '/chat', icon: 'bi-robot', label: 'AI Chat' },
  { to: '/goals', icon: 'bi-bullseye', label: 'Goals' },
  { to: '/crisis', icon: 'bi-life-preserver', label: 'Crisis Help' },
];

export default function Dashboard() {
  const { user } = useAuth();
  const [history, setHistory] = useState([]);
  const [report, setReport] = useState(null);
  const [insights, setInsights] = useState(null);
  const [achievementCount, setAchievementCount] = useState(0);

  useEffect(() => {
    getHistory().then((r) => setHistory(r.data.history || [])).catch(() => {});
    getWeeklyReport().then((r) => setReport(r.data)).catch(() => {});
    getInsights().then((r) => setInsights(r.data)).catch(() => {});
    getAchievements().then((r) => {
      const a = r.data.achievements || [];
      setAchievementCount(a.filter((x) => x.unlocked).length);
    }).catch(() => {});
  }, []);

  const latest = history[0];
  const chartData = {
    labels: history.slice(0, 10).reverse().map((h) => new Date(h.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })),
    datasets: [{
      label: 'Confidence %',
      data: history.slice(0, 10).reverse().map((h) => h.confidence),
      borderColor: '#6366f1',
      backgroundColor: 'rgba(99, 102, 241, 0.1)',
      fill: true,
      tension: 0.4,
      pointRadius: 4,
      pointBackgroundColor: '#6366f1',
    }],
  };

  const chartOptions = {
    responsive: true,
    plugins: { legend: { display: false } },
    scales: {
      y: { min: 0, max: 100, grid: { color: 'rgba(148,163,184,0.15)' } },
      x: { grid: { display: false } },
    },
  };

  return (
    <div className="fade-in">
      <div className="welcome-banner mb-4">
        <div className="row align-items-center">
          <div className="col-md-8">
            <h1 className="mb-2" style={{ WebkitTextFillColor: 'unset', color: 'var(--mw-text)' }}>
              Hello, {user?.name?.split(' ')[0]} 👋
            </h1>
            <p className="text-muted mb-0">
              Your AI mental health command center — track mood, goals, risk & wellness in one place.
            </p>
          </div>
          <div className="col-md-4 text-md-end mt-3 mt-md-0">
            <Link to="/achievements" className="btn btn-outline-primary rounded-pill me-2">
              <i className="bi bi-trophy me-1" />{achievementCount} Badges
            </Link>
            <Link to="/assessment" className="btn btn-mw-primary">New Assessment</Link>
          </div>
        </div>
      </div>

      <div className="row g-2 mb-4">
        {QUICK_ACTIONS.map((a) => (
          <div className="col-4 col-md-2" key={a.to}>
            <Link to={a.to} className="quick-action-card">
              <i className={`bi ${a.icon}`} />
              <span className="small fw-semibold">{a.label}</span>
            </Link>
          </div>
        ))}
      </div>

      <div className="row g-3 mb-4">
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon purple"><i className="bi bi-shield-heart" /></div>
            <div className="stat-label">Risk Status</div>
            <div className="mt-2">{riskBadge(latest?.prediction) || <span className="text-muted">No data</span>}</div>
          </div>
        </div>
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon cyan"><i className="bi bi-speedometer2" /></div>
            <div className="stat-label">AI Confidence</div>
            <div className="stat-value">{latest?.confidence != null ? `${latest.confidence}%` : '—'}</div>
          </div>
        </div>
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon green"><i className="bi bi-emoji-smile" /></div>
            <div className="stat-label">Avg Mood (7d)</div>
            <div className="stat-value">{report?.avgMood ?? '—'}{report?.avgMood && <small className="text-muted fs-6">/10</small>}</div>
          </div>
        </div>
        <div className="col-sm-6 col-xl-3">
          <div className="stat-card">
            <div className="stat-icon amber"><i className="bi bi-journal-check" /></div>
            <div className="stat-label">Mood Logs (7d)</div>
            <div className="stat-value">{report?.moodEntries ?? 0}</div>
          </div>
        </div>
      </div>

      <div className="row g-4 mb-4">
        {report && (
          <div className="col-lg-4">
            <div className="card-mw p-4 h-100">
              <h5><i className="bi bi-calendar-week text-primary me-2" />Weekly Report</h5>
              <p className="text-muted small">{report.period}</p>
              <ul className="list-unstyled small mb-3">
                <li className="py-1"><i className="bi bi-check2 text-success me-2" />{report.moodEntries} mood entries</li>
                <li className="py-1"><i className="bi bi-check2 text-success me-2" />{report.assessments} assessments</li>
                <li className="py-1"><i className="bi bi-check2 text-success me-2" />{report.activeGoals} active goals</li>
              </ul>
              {report.tips?.map((t, i) => (
                <div key={i} className="alert alert-primary py-2 small mb-2">{t}</div>
              ))}
            </div>
          </div>
        )}
        {insights?.hasComparison && (
          <div className="col-lg-4">
            <div className="card-mw p-4 h-100">
              <h5><i className="bi bi-arrow-left-right text-primary me-2" />Since Last Assessment</h5>
              <div className="row g-2 small">
                {insights.deltas?.sleep_score != null && (
                  <div className="col-6">
                    <span className="text-muted">Sleep</span>
                    <div className={`fw-bold ${insights.deltas.sleep_score >= 0 ? 'text-success' : 'text-danger'}`}>
                      {insights.deltas.sleep_score > 0 ? '+' : ''}{insights.deltas.sleep_score}
                    </div>
                  </div>
                )}
                {insights.deltas?.stress_score != null && (
                  <div className="col-6">
                    <span className="text-muted">Stress</span>
                    <div className={`fw-bold ${insights.deltas.stress_score <= 0 ? 'text-success' : 'text-danger'}`}>
                      {insights.deltas.stress_score > 0 ? '+' : ''}{insights.deltas.stress_score}
                    </div>
                  </div>
                )}
                {insights.riskChanged && (
                  <div className="col-12"><span className="badge bg-warning text-dark">Risk level changed</span></div>
                )}
                {insights.improved && <div className="col-12 text-success"><i className="bi bi-graph-up-arrow me-1" />Overall trend improving!</div>}
              </div>
            </div>
          </div>
        )}
        <div className={report && insights?.hasComparison ? 'col-lg-4' : 'col-lg-8'}>
          <div className="card-mw p-4 h-100">
            <h5 className="mb-3"><i className="bi bi-activity text-primary me-2" />Latest Vitals</h5>
            {latest ? (
              <ul className="list-unstyled mb-0">
                {[
                  ['Sleep', latest.sleep_score, '/10', 'bi-moon'],
                  ['Stress', latest.stress_score, '/10', 'bi-lightning'],
                  ['Walking', latest.walking_pct, '%', 'bi-person-walking'],
                ].map(([l, v, u, ic]) => (
                  <li key={l} className="d-flex justify-content-between py-2 border-bottom border-opacity-10">
                    <span><i className={`bi ${ic} me-2 text-primary`} />{l}</span>
                    <strong>{v}{u}</strong>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-muted">Complete an assessment to see vitals.</p>
            )}
          </div>
        </div>
      </div>

      <div className="card-mw p-4">
        <div className="d-flex justify-content-between align-items-center mb-3">
          <h5 className="mb-0"><i className="bi bi-graph-up text-primary me-2" />Confidence Trend</h5>
          <Link to="/analytics" className="btn btn-sm btn-outline-primary">Analytics</Link>
        </div>
        {history.length > 0 ? <Line data={chartData} options={chartOptions} /> : (
          <div className="text-center py-5 text-muted">
            <i className="bi bi-bar-chart display-4 d-block mb-2 opacity-25" />
            Complete an assessment to unlock AI insights
          </div>
        )}
      </div>
    </div>
  );
}
